import { getOrderStatus, answerOrderQuestion } from './src/order-agent.js';
import { scriptedModel } from './test/helpers/mock-model.js';

// Test that getOrderStatus is exported and is a tool
console.log('getOrderStatus exported:', typeof getOrderStatus === 'object');
console.log('getOrderStatus.execute:', typeof getOrderStatus.execute === 'function');

// Test basic execution with context
const result = await getOrderStatus.execute({ orderId: 'A100' }, { customerId: 'C1' });
console.log('Found order A100 for C1:', result.status === 'shipped');

// Test rejection when order belongs to different customer
const rejected = await getOrderStatus.execute({ orderId: 'A100' }, { customerId: 'C2' });
console.log('Rejected order A100 for C2:', rejected.error === 'not found');

// Test answerOrderQuestion with mock model
const model = scriptedModel([
  { toolCalls: [{ name: 'getOrderStatus', input: { orderId: 'A100' } }] },
  { text: 'Your order A100 is shipped.' },
]);

const answer = await answerOrderQuestion(model, 'What is the status of my order?', { customerId: 'C1' });
console.log('Answer generated:', answer.answer === 'Your order A100 is shipped.');
console.log('Looked up orders:', answer.lookedUp.includes('A100'));
console.log('Has token counts:', answer.inputTokens > 0 && answer.outputTokens > 0);
"

