  parameters: z.object({ id: z.string() }),
  execute: async ({ id }) => {
    console.log('Tool executed with id:', id);
    return { id, value: 'found' };
  },
});

const model = scriptedModel([
  { toolCalls: [{ name: 'simpleLookup', input: { id: 'X1' } }], usage: [10, 5] },
